using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class TuneTreeDistances {
 public static string Main(){var root=GameObject.Find("New_Map").transform;var player=UnityEngine.Object.FindObjectsByType<PlayerController>(FindObjectsSortMode.None).FirstOrDefault();var camera=player?(player.characterCamera?player.characterCamera:player.GetComponentInChildren<Camera>()):Camera.main;float gameFov=camera?camera.fieldOfView:60;float sceneFov=SceneView.lastActiveSceneView?SceneView.lastActiveSceneView.camera.fieldOfView:gameFov;float fov=Mathf.Max(gameFov,sceneFov);float denominator=2*Mathf.Tan(fov*.5f*Mathf.Deg2Rad);var hills=root.Find("12_Farmyards_and_boundaries/Low poly hill groves");int count=0;foreach(var l in root.GetComponentsInChildren<LODGroup>().Where(l=>l.name.Contains("Tree")||l.transform.IsChildOf(hills))){float scale=Mathf.Max(Mathf.Abs(l.transform.lossyScale.x),Mathf.Max(Mathf.Abs(l.transform.lossyScale.y),Mathf.Abs(l.transform.lossyScale.z)));float extent=l.size*scale*QualitySettings.lodBias;float detailDistance=l.name.StartsWith("Outer ")?90:110;var levels=l.GetLODs();levels[0].screenRelativeTransitionHeight=Mathf.Clamp(extent/(denominator*35),.001f,.95f);levels[1].screenRelativeTransitionHeight=Mathf.Clamp(extent/(denominator*detailDistance),.0005f,levels[0].screenRelativeTransitionHeight-.0001f);if(levels.Length==4){levels[2].screenRelativeTransitionHeight=Mathf.Clamp(extent/(denominator*(detailDistance*2)),.0002f,levels[1].screenRelativeTransitionHeight-.0001f);levels[3].screenRelativeTransitionHeight=.0001f;}else levels[2].screenRelativeTransitionHeight=.0001f;l.SetLODs(levels);count++;}EditorSceneManager.SaveScene(root.gameObject.scene);return "Applied detailed-tree targets 110m inside / 90m outside to "+count+" groups using reference FOV="+fov+" (game="+gameFov+", Scene View="+sceneFov+"). Faceted proxies only beyond this range. Global quality unchanged.";}
}

